-- Карусель: кілька картинок на одне оголошення (порядок = порядок карток)
ALTER TABLE cm_ads ADD COLUMN files_json TEXT NOT NULL DEFAULT '[]';
INSERT INTO changelog (title, body, created_at) VALUES ('Кампанії: карусель', 'В оголошенні з форматом «Карусель» можна завантажити кілька картинок одразу (до 10) — виділи всі файли або перетягни пачкою. Картки стоять у порядку завантаження, кожну можна прибрати або посунути ←/→. Прев''ю гортається як у Meta, а «Тексти під цей креатив» Джері пише, подивившись на всі картки (до 5). Якщо завантажити кілька файлів в оголошення іншого формату — воно саме стане каруселлю.', datetime('now'));
